/* ───── 고양이 그림 (걷기 6프레임 · 앉기 · 하품 · 정면 · 잠) — 꼬리 그림(IMG.tail)이 있으면 따로 흔들어요 ───── */
const flip = cat.querySelector('.nyc-flip');
const W0 = IMG.walk, T0 = IMG.tail, K = W0.k, FW = Math.round(W0.w * K), FH = Math.round(W0.h * K);
const cv = document.createElement('canvas'); cv.className = 'nyc-pose p-walk'; cv.width = FW; cv.height = FH; cv.style.width = W0.w + 'px'; cv.style.height = W0.h + 'px';
const ctx = cv.getContext('2d');
const ld = (src) => { const i = new Image(); i.src = src; return i; };
const bodyImg = ld(W0.src), tailImg = T0 ? ld(T0.src) : null;
const mk = (cls, im) => { const el = document.createElement('img'); el.className = 'nyc-pose ' + cls; el.style.width = im.w + 'px'; el.style.height = im.h + 'px'; el.src = im.src; el.alt = ''; el.draggable = false; return el; };
