/* ───── 움직임 ───── */
const VW = () => window.innerWidth, CW = 140, CH = 112;
let x = 40 + Math.random() * 200, dir = 1, state = 'walk', target = 300, until = 0, open = false, speed = 58, petCount = 0, petT = 0;
